def trazer_erros_antigos(apps, schema_editor):
    """As respostas erradas de antes do caderno de erros existir também entram nele."""
    Resposta = apps.get_model('questoes', 'Resposta')
    Erro = apps.get_model('questoes', 'Erro')
    erros = {}
    for r in Resposta.objects.filter(acertou=False).order_by('respondida_em', 'id'):
        erro = erros.get(r.questao_id)
        if erro is None:
            erros[r.questao_id] = Erro(questao_id=r.questao_id, resposta_dada=r.resposta_dada,
                                       criado_em=r.respondida_em, errou_em=r.respondida_em)
        else:
            erro.vezes += 1
            erro.resposta_dada, erro.errou_em = r.resposta_dada, r.respondida_em
    Erro.objects.bulk_create(erros.values())


